parameters.command:
SKILL_DIR="/home/azureuser/projects/skills/tmp/skills/uipath-maestro-flow"
FLOW="/work/output/artifacts/skill-flow-feet-inches/FeetInches/FeetInches/FeetInches.flow"

# Fetch definitions for all node types we need
SWITCH_DEF=$(uip maestro flow registry get core.logic.switch --output json | python3 -c "import sys,json; d=json.load(sys.stdin); print(json.dumps(d['Data']['Node']))")
SCRIPT_DEF=$(uip maestro flow registry get core.action.script --output json | python3 -c "import sys,json; d=json.load(sys.stdin); print(json.dumps(d['Data']['Node']))")
END_DEF=$(uip maestro flow registry get core.control.end --output json | python3 -c "import sys,json; d=json.load(sys.stdin); print(json.dumps(d['Data']['Node']))")

# Write plan
cat > /tmp/feetinches_plan.json << 'PLAN'
{
  "ops": [
    {
      "op": "add-variable",
      "id": "value",
      "direction": "in",
      "type": "number",
      "description": "The numeric value to convert"
    },
    {
      "op": "add-variable",
      "id": "direction",
      "direction": "in",
      "type": "string",
      "description": "Conversion direction: f2i, i2f, or y2f"
    },
    {
      "op": "add-variable",
      "id": "result",
      "direction": "out",
      "type": "number",
      "description": "The converted value"
    },
    {
      "op": "add-node",
      "id": "switchDirection",
      "type": "core.logic.switch",
      "typeVersion": "1.1",
      "label": "Switch on direction",
      "inputs": {
        "cases": [
          {
            "id": "f2i",
            "label": "Feet to Inches",
            "expression": "$vars.start.output.direction === 'f2i'"
          },
          {
            "id": "i2f",
            "label": "Inches to Feet",
            "expression": "$vars.start.output.direction === 'i2f'"
          },
          {
            "id": "y2f",
            "label": "Yards to Feet",
            "expression": "$vars.start.output.direction === 'y2f'"
          }
        ]
      }
    },
    {
      "op": "add-node",
      "id": "convertF2I",
      "type": "core.action.script",
      "typeVersion": "1.1",
      "label": "Feet to Inches (× 12)",
      "inputs": {
        "script": "return { converted: $vars.start.output.value * 12 };"
      }
    },
    {
      "op": "add-node",
      "id": "convertI2F",
      "type": "core.action.script",
      "typeVersion": "1.1",
      "label": "Inches to Feet (÷ 12)",
      "inputs": {
        "script": "return { converted: $vars.start.output.value / 12 };"
      }
    },
    {
      "op": "add-node",
      "id": "convertY2F",
      "type": "core.action.script",
      "typeVersion": "1.1",
      "label": "Yards to Feet (× 3)",
      "inputs": {
        "script": "return { converted: $vars.start.output.value * 3 };"
      }
    },
    {
      "op": "add-node",
      "id": "end",
      "type": "core.control.end",
      "typeVersion": "1.0",
      "label": "End",
      "outputs": "none"
    },
    {
      "op": "add-edge",
      "source": "start",
      "sourcePort": "output",
      "target": "switchDirection",
      "targetPort": "input"
    },
    {
      "op": "add-edge",
      "source": "switchDirection",
      "sourcePort": "case-f2i",
      "target": "convertF2I",
      "targetPort": "input"
    },
    {
      "op": "add-edge",
      "source": "switchDirection",
      "sourcePort": "case-i2f",
      "target": "convertI2F",
      "targetPort": "input"
    },
    {
      "op": "add-edge",
      "source": "switchDirection",
      "sourcePort": "case-y2f",
      "target": "convertY2F",
      "targetPort": "input"
    },
    {
      "op": "add-edge",
      "source": "convertF2I",
      "sourcePort": "success",
      "target": "end",
      "targetPort": "input"
    },
    {
      "op": "add-edge",
      "source": "convertI2F",
      "sourcePort": "success",
      "target": "end",
      "targetPort": "input"
    },
    {
      "op": "add-edge",
      "source": "convertY2F",
      "sourcePort": "success",
      "target": "end",
      "targetPort": "input"
    },
    {
      "op": "add-output-mapping",
      "endNode": "end",
      "var": "result",
      "source": "=js:$vars.convertF2I.output.converted ?? $vars.convertI2F.output.converted ?? $vars.convertY2F.output.converted"
    }
  ]
}
PLAN

python3 "$SKILL_DIR/scripts/flow_edit.py" apply --flow "$FLOW" --plan /tmp/feetinches_plan.json \
  --def-dir <(echo "$SWITCH_DEF") 2>/dev/null || true

# Inject definitions manually since --def-dir doesn't accept process substitution
# Instead, build a temp dir with the definition files
mkdir -p /tmp/flow_defs
echo "$SWITCH_DEF" > /tmp/flow_defs/core.logic.switch.json
echo "$SCRIPT_DEF" > /tmp/flow_defs/core.action.script.json
echo "$END_DEF" > /tmp/flow_defs/core.control.end.json

python3 "$SKILL_DIR/scripts/flow_edit.py" apply --flow "$FLOW" --plan /tmp/feetinches_plan.json
echo "EXIT: $?"

